function GardenPlantLabelEmbosserMaker.completeMaking(m) local q=1.0+(GardenPlantLabelEmbosserMaker.getQualityBonus()/100); if GardenPlantLabelEmbosserMaker.maker then q=q+(GardenPlantLabelEmbosserMaker.maker.skill/140) end; q=math.min(2.5,q); GardenPlantLabelEmbosserMaker.productStock[m.productType]=(GardenPlantLabelEmbosserMaker.productStock[m.productType] or 0)+m.quantity; GardenPlantLabelEmbosserMaker.totalProducts=GardenPlantLabelEmbosserMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GardenPlantLabelEmbosserMaker.maker then GardenPlantLabelEmbosserMaker.maker.itemsMade=GardenPlantLabelEmbosserMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GardenPlantLabelEmbosserMaker.maker.skill=math.min(100,GardenPlantLabelEmbosserMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žig izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gardenplantlabelembosser.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
